domain: {{m}}, {{p}}, {{q}}, {{n}}

sign: f'(x)
  {{m}},{{p}}: ?{{if:A>0|+|-}}
  {{p}}: z
  {{p}},{{q}}: ?{{if:A>0|-|+}}
  {{q}}: z
  {{q}},{{n}}: ?{{if:A>0|+|-}}

variation: f(x)
  {{m}}: {{Fm}}, {{if:A>0|bottom|top}}
  {{p}}: ?{{Fp}}, {{if:A>0|top|bottom}}
  {{q}}: ?{{Fq}}, {{if:A>0|bottom|top}}
  {{n}}: {{Fn}}, {{if:A>0|top|bottom}}
